<?php $festival=sc_festival_config();if(!$festival['enabled'])return; ?>
<link rel="stylesheet" href="<?= theme_url('assets/css/festivals.css') ?>?v=1">
<div id="sc-festive" class="sc-festive sc-festive-<?= sc_e($festival['festival']) ?>" data-config="<?= sc_e(json_encode($festival)) ?>"><canvas aria-hidden="true"></canvas><div class="sc-festival-decor" aria-hidden="true"><?php if($festival['festival']==='diwali'): ?><i class="sc-diya"></i><i class="sc-diya"></i><i class="sc-diya"></i><?php elseif(in_array($festival['festival'],['eid','bakr_eid','ramadan'],true)): ?><span class="sc-crescent">&#9790;</span><span class="sc-lantern">&#10022;</span><?php elseif($festival['festival']==='christmas'): ?><span class="sc-season-star">&#9733;</span><?php endif; ?></div><aside class="sc-festival-badge"><small><?= $festival['preview']?'ADMIN PREVIEW · ':'' ?><?= sc_e($festival['name']) ?></small><span><?= sc_e($festival['greeting']) ?></span><button type="button" id="sc-festival-toggle" aria-pressed="false">Pause effects</button></aside><?php if($festival['effect']==='fireworks'): ?><button type="button" class="sc-rocket-launch" aria-label="Launch a festive sky rocket">Launch a sky rocket &#8599;</button><?php endif; ?></div>
<script defer src="<?= theme_url('assets/js/festivals.js') ?>?v=1"></script>
